insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  14,
  $wyb$A scheduled Python job that scans your HubSpot pipeline for deals with no activity in 7+ days, pulls the contact and note history for each one, asks the AI to write a personalized follow-up referencing real context, saves it as a Gmail draft, and pings Slack when drafts are ready. A pricing guard blocks any generated email that mentions discounts or dollar amounts before it's ever saved, and a seen-deals tracker stops a rerun from drafting the same follow-up twice.$wyb$,
  $wyl$[
  "Query the HubSpot CRM API for deals and paginate through a large pipeline",
  "Separate a pure staleness/filtering rule from the live API call around it, so it can be tested offline",
  "Enrich a record with associated contacts and notes, handling missing data gracefully",
  "Write a system prompt with house rules, then enforce the riskiest rule (never discuss pricing) in code, not just in the prompt",
  "Track which records have already been processed so a scheduled rerun never creates a duplicate",
  "Save AI-drafted emails safely for human review instead of auto-sending"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "130 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A HubSpot account (free tier works) with a Private App token",
    "A Gmail account with the Gmail API enabled",
    "(Optional) A Slack Incoming Webhook URL"
  ],
  "outcomes": [
    "Scan your HubSpot pipeline for deals with no activity in 7+ days, using a staleness rule you can unit-test",
    "Pull contact and note context for each stale deal, without crashing on the many deals missing one or the other",
    "Have the AI write a personalized, on-brand follow-up - with a code-level guard that blocks any pricing or discount language before it's saved",
    "Track which deals already got a draft so a daily rerun never creates a duplicate",
    "Save every email as a Gmail draft and ping Slack when drafts are ready"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Set up sdt_ai.py and find your stale deals",
      "time": "35 min",
      "description": "Before writing any emails, wire up the shared AI gateway and find out which deals actually need attention. The staleness rule is written and tested as a pure function first, so you know it's correct before it ever touches your real HubSpot pipeline.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# Overridable via .env if you ever want to try a different model.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-2.5-flash\")\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                GEMINI_URL, params={\"key\": api_key}, json=payload, timeout=90\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            last_problem = \"Gemini is busy (503 - high demand on the free tier)\"\n            time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# HubSpot - create a Private App at Settings > Integrations > Private Apps\n# with crm.objects.deals.read, crm.objects.contacts.read, and\n# crm.objects.notes.read scopes\nHUBSPOT_TOKEN=paste_your_own_private_app_token_here\n\n# Optional - a Slack Incoming Webhook URL for the ready notification\n# SLACK_WEBHOOK_URL=https://hooks.slack.com/services/...\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `hubspot_client.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the CRM Lead Follow-Up Agent.\n\nThis file talks to HubSpot: it fetches your open deals and tells you\nwhich ones have gone stale. The staleness check (is_stale) is pure\nPython with no network call in it, which is why the self-test at the\nbottom can check it thoroughly without a HubSpot account. Only\nget_stale_deals() itself needs a real login and a real HUBSPOT_TOKEN.\n\"\"\"\n\nimport os\nfrom datetime import datetime, timedelta, timezone\n\nfrom dotenv import load_dotenv\nfrom hubspot import HubSpot\n\nload_dotenv()\n\n# Deals in these stages are done - a \"stale\" closed deal isn't a signal\n# to follow up on, it's just a deal nobody filed away yet.\nCLOSED_STAGES = {\"closedwon\", \"closedlost\"}\n\nDEAL_PROPERTIES = [\"dealname\", \"dealstage\", \"hs_lastmodifieddate\", \"amount\"]\n\n\ndef is_stale(deal_properties, cutoff_days=7, now=None):\n    \"\"\"\n    Returns True if a deal's properties dict shows no activity in\n    cutoff_days days and it isn't already closed.\n\n        is_stale({\"dealstage\": \"presentation\", \"hs_lastmodifieddate\": \"2026-01-01T00:00:00.000Z\"})\n\n    Pure function - no network call, no HubSpot client needed - which is\n    why this can be unit tested with fake data below, before you ever\n    touch a real HubSpot account.\n\n    A deal missing hs_lastmodifieddate entirely is treated as stale\n    rather than raising - a record HubSpot never timestamped deserves at\n    least as much of a look as one timestamped a month ago.\n    \"\"\"\n    now = now or datetime.now(timezone.utc)\n    cutoff = now - timedelta(days=cutoff_days)\n\n    if deal_properties.get(\"dealstage\") in CLOSED_STAGES:\n        return False\n\n    last_modified = deal_properties.get(\"hs_lastmodifieddate\")\n    if not last_modified:\n        return True\n\n    modified_at = datetime.fromisoformat(last_modified.replace(\"Z\", \"+00:00\"))\n    return modified_at < cutoff\n\n\ndef get_stale_deals(days=7):\n    \"\"\"\n    Fetches every open deal from HubSpot and returns the stale ones.\n\n        stale = get_stale_deals(days=7)\n\n    Paginates using HubSpot's `after` cursor, so this works correctly on\n    a pipeline with more than 100 open deals, not just the first page.\n    \"\"\"\n    token = os.environ.get(\"HUBSPOT_TOKEN\")\n    if not token:\n        raise RuntimeError(\n            \"No HUBSPOT_TOKEN found. Create a Private App in HubSpot \"\n            \"(Settings > Integrations > Private Apps) with \"\n            \"crm.objects.deals.read scope, and add the token to .env.\"\n        )\n\n    client = HubSpot(access_token=token)\n    stale = []\n    after = None\n\n    while True:\n        page = client.crm.deals.basic_api.get_page(\n            limit=100, properties=DEAL_PROPERTIES, after=after\n        )\n        for deal in page.results:\n            if is_stale(deal.properties, cutoff_days=days):\n                stale.append(deal)\n\n        if not page.paging or not page.paging.next:\n            break\n        after = page.paging.next.after\n\n    return stale\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the staleness logic works - no\n    # HubSpot account or network call needed:  python hubspot_client.py\n    now = datetime(2026, 9, 2, tzinfo=timezone.utc)\n\n    stale_deal = {\"dealstage\": \"presentation\", \"hs_lastmodifieddate\": \"2026-08-01T00:00:00.000Z\"}\n    fresh_deal = {\"dealstage\": \"presentation\", \"hs_lastmodifieddate\": \"2026-09-01T00:00:00.000Z\"}\n    closed_deal = {\"dealstage\": \"closedwon\", \"hs_lastmodifieddate\": \"2026-01-01T00:00:00.000Z\"}\n    no_date_deal = {\"dealstage\": \"presentation\"}\n\n    assert is_stale(stale_deal, cutoff_days=7, now=now) is True\n    print(\"Stale deal (32 days old) correctly flagged as stale.\")\n\n    assert is_stale(fresh_deal, cutoff_days=7, now=now) is False\n    print(\"Fresh deal (1 day old) correctly NOT flagged as stale.\")\n\n    assert is_stale(closed_deal, cutoff_days=7, now=now) is False\n    print(\"Closed-won deal correctly NOT flagged as stale, no matter how old.\")\n\n    assert is_stale(no_date_deal, cutoff_days=7, now=now) is True\n    print(\"Deal with no hs_lastmodifieddate at all correctly treated as stale.\")\n\n    print(\"\\nAll staleness checks passed. Real HubSpot deal properties have this exact shape.\")\n",
          "verify": "Run `python hubspot_client.py`. You should see four lines, each ending `correctly ...` (flagged as stale / NOT flagged as stale / NOT flagged / treated as stale), ending with `All staleness checks passed. Real HubSpot deal properties have this exact shape.`"
        },
        {
          "instruction": "Now run it against your real HubSpot account:",
          "prompt": "python -c \"from hubspot_client import get_stale_deals; [print(d.properties['dealname'], '-', d.properties['dealstage']) for d in get_stale_deals()]\"",
          "verify": "You should see the names and stages of your actually-stale open deals. If nothing prints and you know you have stale deals, temporarily lower `days` to confirm the filter logic works, then set it back to 7. If you get a 401, your Private App token is missing a scope."
        }
      ],
      "goFurther": "Check a couple of the listed deals manually in HubSpot - confirm they really haven't been touched in 7+ days and aren't closed."
    },
    {
      "number": 2,
      "title": "Enrich each deal with contact and note context",
      "time": "25 min",
      "description": "A generic follow-up is worse than no follow-up. This build pulls real contact and note context for each stale deal, tested against fake HubSpot response shapes first.",
      "steps": [
        {
          "instruction": "Create `enrich.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the CRM Lead Follow-Up Agent.\n\nA generic follow-up is worse than no follow-up. This file pulls the\ncontact and recent note history for a deal so writer.py has real\ncontext to personalize with. The two parsing helpers (parse_contact,\nparse_notes) are pure functions with no network call, tested below\nagainst fake API response shapes.\n\"\"\"\n\n# How many recent notes to pull per deal. A MONEY decision as much as a\n# UX one: every note becomes extra input-token cost in writer.py's\n# prompt, and a deal rarely needs its entire note history to write one\n# good follow-up sentence.\nMAX_NOTES = 5\n\n\ndef parse_contact(raw_contact):\n    \"\"\"\n    Turns a raw HubSpot contact object into the simple shape this\n    project uses everywhere:\n\n        {\"first_name\": \"...\", \"last_name\": \"...\", \"email\": \"...\", \"job_title\": \"...\"}\n\n    Returns None if raw_contact is None - a deal with no associated\n    contact is common and must not crash enrichment. Callers check for\n    None rather than this function inventing a placeholder name.\n    \"\"\"\n    if raw_contact is None:\n        return None\n\n    props = raw_contact.properties if hasattr(raw_contact, \"properties\") else raw_contact\n    return {\n        \"first_name\": props.get(\"firstname\", \"\").strip(),\n        \"last_name\": props.get(\"lastname\", \"\").strip(),\n        \"email\": props.get(\"email\", \"\").strip(),\n        \"job_title\": props.get(\"jobtitle\", \"\").strip(),\n    }\n\n\ndef parse_notes(raw_notes, max_notes=MAX_NOTES):\n    \"\"\"\n    Turns a list of raw HubSpot note objects into a list of clean text\n    strings, capped at max_notes.\n\n        parse_notes(raw_notes) -> [\"Called, left voicemail.\", \"Sent pricing deck.\"]\n\n    Skips any note with an empty or missing body rather than including\n    a blank string a prompt would have to explain away.\n    \"\"\"\n    notes = []\n    for raw_note in raw_notes:\n        props = raw_note.properties if hasattr(raw_note, \"properties\") else raw_note\n        body = (props.get(\"hs_note_body\") or \"\").strip()\n        if body:\n            notes.append(body)\n    return notes[:max_notes]\n\n\ndef enrich_deal(client, deal):\n    \"\"\"\n    The main function. Given a HubSpot client and one deal, returns:\n\n        {\"deal\": deal, \"contact\": parsed_contact_or_None, \"recent_notes\": [...]}\n\n    Looks up only the FIRST associated contact and up to MAX_NOTES recent\n    notes - this project optimizes for \"enough context to personalize\n    one email,\" not a complete CRM export.\n    \"\"\"\n    contact = None\n    contact_associations = client.crm.deals.associations_api.get_all(\n        deal.id, to_object_type=\"contacts\"\n    )\n    if contact_associations.results:\n        contact_id = contact_associations.results[0].to_object_id\n        raw_contact = client.crm.contacts.basic_api.get_by_id(\n            contact_id, properties=[\"firstname\", \"lastname\", \"email\", \"jobtitle\"]\n        )\n        contact = parse_contact(raw_contact)\n\n    note_associations = client.crm.deals.associations_api.get_all(deal.id, to_object_type=\"notes\")\n    raw_notes = [\n        client.crm.objects.notes.basic_api.get_by_id(assoc.to_object_id, properties=[\"hs_note_body\"])\n        for assoc in note_associations.results[:MAX_NOTES]\n    ]\n\n    return {\n        \"deal\": deal,\n        \"contact\": contact,\n        \"recent_notes\": parse_notes(raw_notes),\n    }\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no HubSpot\n    # account or network call needed:  python enrich.py\n    print(\"Checking parse_contact()...\")\n    full_contact = {\"firstname\": \"Amaka\", \"lastname\": \"Obi\", \"email\": \"amaka@example.com\", \"jobtitle\": \"VP Sales\"}\n    result = parse_contact(full_contact)\n    assert result == {\"first_name\": \"Amaka\", \"last_name\": \"Obi\", \"email\": \"amaka@example.com\", \"job_title\": \"VP Sales\"}\n    print(\"  OK - full contact parsed correctly\")\n\n    assert parse_contact(None) is None\n    print(\"  OK - a deal with no contact correctly returned None\")\n\n    sparse_contact = {\"firstname\": \"Chidi\", \"email\": \"chidi@example.com\"}\n    result = parse_contact(sparse_contact)\n    assert result[\"job_title\"] == \"\"\n    print(\"  OK - a contact missing jobtitle/lastname defaulted to '' instead of crashing\")\n\n    print(\"\\nChecking parse_notes()...\")\n    raw_notes = [\n        {\"hs_note_body\": \"Called, left voicemail.\"},\n        {\"hs_note_body\": \"\"},\n        {\"hs_note_body\": \"  Sent the pricing deck.  \"},\n    ]\n    notes = parse_notes(raw_notes)\n    assert notes == [\"Called, left voicemail.\", \"Sent the pricing deck.\"]\n    print(\"  OK - empty note body correctly skipped, whitespace trimmed:\", notes)\n\n    many_notes = [{\"hs_note_body\": f\"Note {i}\"} for i in range(10)]\n    assert len(parse_notes(many_notes)) == MAX_NOTES\n    print(f\"  OK - capped at {MAX_NOTES} even though 10 notes were given\")\n\n    print(\"\\nAll parsing checks passed. Real HubSpot contact/note objects have this exact shape.\")\n",
          "verify": "Run `python enrich.py`. You should see the full contact parsed correctly, a missing contact correctly returning None, a sparse contact defaulting missing fields to '', an empty note skipped while whitespace is trimmed, and 10 fake notes correctly capped at 5 - ending with `All parsing checks passed.`"
        }
      ],
      "goFurther": "🛠️ Add a company lookup: fetch the associated company's name and industry the same way enrich_deal() looks up contacts, and add it to the returned dict for even better personalization in Build 3."
    },
    {
      "number": 3,
      "title": "Generate personalized emails - with a pricing guard",
      "time": "30 min",
      "description": "This is where deal context turns into an email a rep would actually send. It's also where this project makes its core safety promise real: a generated email is checked for pricing or discount language in code before it's ever saved as a draft, rather than trusting the system prompt's rules alone.",
      "steps": [
        {
          "instruction": "Create `writer.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the CRM Lead Follow-Up Agent.\n\nThis is where deal context turns into an email a rep would actually\nsend. It also carries this project's safety guard: a generated email is\nchecked for banned topics (pricing, discounts) before it's ever saved\nas a draft, since a rep should decide pricing language themselves, not\nhave the AI improvise it into an automated follow-up.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\nSYSTEM_PROMPT = \"\"\"You write short, on-brand sales follow-up emails.\n\nRules:\n- Never mention pricing, discounts, or specific dollar amounts.\n- End with exactly ONE clear call-to-action, e.g. \"Free for a 15-min call this week?\"\n- Friendly, professional tone. No corporate jargon (\"synergy\", \"circle back\", \"touch base\").\n- Under 100 words. No subject line, just the body.\"\"\"\n\n# Words that should never appear in an automated follow-up - a rep\n# should decide pricing language themselves, not have the AI improvise\n# it into a draft that goes out under their name.\nBANNED_TOPICS = [\"discount\", \"% off\", \"price is\", \"pricing is\", \"free trial\"]\n\n\ndef build_prompt(enriched):\n    \"\"\"\n    Turns one enriched deal (from enrich.py) into the prompt we send the\n    AI. Pure function, no network call - tested below against fake\n    enriched data.\n    \"\"\"\n    deal = enriched[\"deal\"]\n    contact = enriched[\"contact\"]\n    notes = enriched[\"recent_notes\"]\n\n    contact_line = (\n        f\"Contact: {contact['first_name']} {contact['last_name']}, {contact['job_title']}\"\n        if contact\n        else \"Contact: unknown (write a slightly more general greeting)\"\n    )\n\n    if notes:\n        notes_block = \"\\n\".join(f\"- {note}\" for note in notes)\n    else:\n        notes_block = \"(no notes on file - do not invent a past conversation, keep it based on the deal stage only)\"\n\n    return f\"\"\"{contact_line}\nDeal: {deal.properties['dealname']}, currently in stage \"{deal.properties['dealstage']}\"\n\nRecent notes:\n{notes_block}\n\nWrite the follow-up email body now.\"\"\"\n\n\ndef contains_banned_topic(email_text):\n    \"\"\"\n    Returns True if the generated email mentions a banned topic.\n\n        contains_banned_topic(\"Let's discuss a 10% discount\") -> True\n\n    Case-insensitive substring check - deliberately simple and a little\n    over-eager rather than a fragile attempt at true language\n    understanding. A false positive here just means a rep double-checks\n    one email; a false negative means an unauthorized discount goes out\n    under their name.\n    \"\"\"\n    lowered = email_text.lower()\n    return any(topic in lowered for topic in BANNED_TOPICS)\n\n\ndef write_followup(enriched):\n    \"\"\"\n    The main function. Give it one enriched deal, get back the email\n    body - or raises ValueError if the AI ignored the pricing rule, so\n    main.py never silently saves a draft that breaks house rules.\n    \"\"\"\n    prompt = build_prompt(enriched)\n    email_text = ask_ai(prompt, system=SYSTEM_PROMPT, max_tokens=250, project=\"crm-followup-agent\")\n\n    if contains_banned_topic(email_text):\n        raise ValueError(\n            \"The AI mentioned pricing or a discount despite being told not to. \"\n            \"Refusing to save this as a draft automatically - review it manually:\\n\\n\"\n            + email_text\n        )\n\n    return email_text\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the prompt-building and the\n    # banned-topic guard work - no AI call, no credits spent:  python writer.py\n\n    class _FakeDeal:\n        def __init__(self, properties):\n            self.properties = properties\n\n    print(\"Checking build_prompt() with a full contact and notes...\")\n    enriched = {\n        \"deal\": _FakeDeal({\"dealname\": \"Acme Corp - Platform License\", \"dealstage\": \"presentation\"}),\n        \"contact\": {\"first_name\": \"Amaka\", \"last_name\": \"Obi\", \"email\": \"amaka@acme.com\", \"job_title\": \"VP Sales\"},\n        \"recent_notes\": [\"Demo went well, asked about integrations.\", \"Following up next week.\"],\n    }\n    prompt = build_prompt(enriched)\n    assert \"Amaka Obi\" in prompt\n    assert \"Demo went well\" in prompt\n    print(\"  OK - contact and notes correctly included\")\n\n    print(\"\\nChecking build_prompt() with no contact and no notes...\")\n    bare = {\n        \"deal\": _FakeDeal({\"dealname\": \"Bare Deal\", \"dealstage\": \"qualified\"}),\n        \"contact\": None,\n        \"recent_notes\": [],\n    }\n    prompt = build_prompt(bare)\n    assert \"unknown\" in prompt\n    assert \"do not invent a past conversation\" in prompt\n    print(\"  OK - missing contact/notes handled without crashing, and the AI is told not to invent history\")\n\n    print(\"\\nChecking contains_banned_topic()...\")\n    assert contains_banned_topic(\"We can offer you a 20% discount this week.\")\n    assert contains_banned_topic(\"Let's start with a free trial.\")\n    assert not contains_banned_topic(\"Free for a quick call this week?\")\n    print(\"  OK - pricing/discount language correctly flagged, an unrelated 'free' correctly left alone\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python writer.py` (no AI call, no credits spent - this only tests prompt-building and the pricing guard against fake data). You should see the full-contact prompt correctly including the contact name and notes, the bare-deal prompt correctly telling the AI not to invent history, and the banned-topic guard correctly catching a discount mention and a free-trial mention while leaving an unrelated 'free for a call' phrase alone - ending with `All checks passed.`"
        }
      ],
      "goFurther": "Adjust SYSTEM_PROMPT's rules to match your own company's tone (more casual, or always sign off with a specific name) and regenerate a real email for one enriched deal - confirm the tone actually shifts."
    },
    {
      "number": 4,
      "title": "Prevent duplicates, save drafts, and notify Slack",
      "time": "40 min",
      "description": "Wire everything into one script that's safe to run every weekday morning without creating a duplicate draft for a deal it already handled yesterday.",
      "steps": [
        {
          "instruction": "Create `seen_tracker.py` with this code:",
          "prompt": "\"\"\"\nStep 4 of the CRM Lead Follow-Up Agent (part 1) - remembers which deals\nalready got a follow-up drafted, so rerunning main.py every weekday\nmorning doesn't create a duplicate Gmail draft for the same deal.\n\"\"\"\n\nimport json\nimport os\n\nSEEN_FILE = \"seen_deals.json\"\n\n\ndef load_seen_ids(path=SEEN_FILE):\n    \"\"\"Returns the set of deal IDs already followed up on. Empty set on first run.\"\"\"\n    if not os.path.exists(path):\n        return set()\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        return set(json.load(f))\n\n\ndef save_seen_ids(seen_ids, path=SEEN_FILE):\n    \"\"\"Persists the set of followed-up deal IDs to disk.\"\"\"\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        json.dump(sorted(seen_ids), f)\n\n\ndef filter_unseen(deals, seen_ids):\n    \"\"\"\n    Returns only the deals whose id is NOT already in seen_ids.\n\n        fresh = filter_unseen(stale_deals, seen_ids)\n\n    Pure function - this is the actual duplicate-prevention logic, kept\n    separate from the file I/O above so it can be tested without ever\n    touching disk.\n    \"\"\"\n    return [deal for deal in deals if deal.id not in seen_ids]\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the logic works:  python seen_tracker.py\n    class _FakeDeal:\n        def __init__(self, deal_id):\n            self.id = deal_id\n\n    deals = [_FakeDeal(\"1\"), _FakeDeal(\"2\"), _FakeDeal(\"3\")]\n    seen = {\"2\"}\n\n    fresh = filter_unseen(deals, seen)\n    fresh_ids = [d.id for d in fresh]\n    assert fresh_ids == [\"1\", \"3\"]\n    print(\"Deal 2 (already seen) correctly filtered out. Remaining:\", fresh_ids)\n\n    print(\"\\nChecking save/load round-trip through a real temp file...\")\n    import tempfile\n    tmp_path = os.path.join(tempfile.gettempdir(), \"sdt_test_seen_deals.json\")\n    save_seen_ids({\"1\", \"2\", \"3\"}, path=tmp_path)\n    loaded = load_seen_ids(path=tmp_path)\n    assert loaded == {\"1\", \"2\", \"3\"}\n    os.remove(tmp_path)\n    print(\"Confirmed: saved IDs match what was loaded back.\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python seen_tracker.py`. You should see deal '2' correctly filtered out of a 3-deal list, then a save/load round-trip through a real temp file confirming the saved IDs match what was loaded back, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `gmail_draft.py` with this code:",
          "prompt": "\"\"\"\nStep 4 of the CRM Lead Follow-Up Agent (part 2) - saves a generated\nfollow-up as a Gmail draft.\n\nUses the exact same OAuth pattern as the Gmail AI Triage Agent from\nBuilder 1 (gmail.compose scope only - this can create drafts, never\nsend mail on its own). If you already have a token.json from that\nproject with gmail.compose access, you can reuse it here.\n\"\"\"\n\nimport base64\nimport email.mime.text\nimport os\n\nfrom google.auth.transport.requests import Request\nfrom google.oauth2.credentials import Credentials\nfrom google_auth_oauthlib.flow import InstalledAppFlow\nfrom googleapiclient.discovery import build\n\nSCOPES = [\"https://www.googleapis.com/auth/gmail.compose\"]\nTOKEN_FILE = \"token.json\"\nCREDENTIALS_FILE = \"credentials.json\"\n\n\ndef get_gmail_service():\n    \"\"\"\n    Logs you in to your own Gmail account and returns a ready-to-use API\n    client. See the Gmail AI Triage Agent (Builder 1) for the full setup\n    walkthrough if this is your first time - same pattern, narrower scope.\n    \"\"\"\n    creds = None\n    if os.path.exists(TOKEN_FILE):\n        creds = Credentials.from_authorized_user_file(TOKEN_FILE, SCOPES)\n\n    if not creds or not creds.valid:\n        if creds and creds.expired and creds.refresh_token:\n            creds.refresh(Request())\n        else:\n            if not os.path.exists(CREDENTIALS_FILE):\n                raise FileNotFoundError(\n                    \"credentials.json not found. Download it from Google Cloud \"\n                    \"Console > APIs & Services > Credentials, and save it in \"\n                    \"this same folder.\"\n                )\n            flow = InstalledAppFlow.from_client_secrets_file(CREDENTIALS_FILE, SCOPES)\n            creds = flow.run_local_server(port=0)\n\n        with open(TOKEN_FILE, \"w\") as token_file:\n            token_file.write(creds.to_json())\n\n    return build(\"gmail\", \"v1\", credentials=creds)\n\n\ndef save_gmail_draft(service, to_email, subject, body):\n    \"\"\"\n    Saves body as a Gmail DRAFT addressed to to_email. Never sends\n    anything - same safety boundary as the Gmail Triage Agent: a bad\n    follow-up can leave the wrong draft sitting in Drafts, but it can\n    never mail someone without a human reading it first.\n    \"\"\"\n    mime_message = email.mime.text.MIMEText(body)\n    mime_message[\"to\"] = to_email\n    mime_message[\"subject\"] = subject\n    raw = base64.urlsafe_b64encode(mime_message.as_bytes()).decode()\n\n    service.users().drafts().create(userId=\"me\", body={\"message\": {\"raw\": raw}}).execute()\n\n\nif __name__ == \"__main__\":\n    print(\"This file only wraps live Gmail API calls - there's no offline\")\n    print(\"self-test to run here. It's exercised for real in Build 4's main.py.\")\n",
          "verify": "This file only wraps live Gmail API calls, so running it directly just prints a note - it's exercised for real in the next step."
        },
        {
          "instruction": "Create `notify.py` with this code:",
          "prompt": "\"\"\"\nStep 4 of the CRM Lead Follow-Up Agent (part 3) - pings Slack once\ndrafts are ready, so reps don't have to remember to check Gmail.\n\"\"\"\n\nimport requests\n\n\ndef build_message(count):\n    \"\"\"\n    Turns a draft count into the exact Slack message text. Pure\n    function - tested below without a real webhook.\n    \"\"\"\n    if count == 1:\n        return \"1 stale deal just got an AI-drafted follow-up - check your Gmail drafts!\"\n    return f\"{count} stale deals just got AI-drafted follow-ups - check your Gmail drafts!\"\n\n\ndef notify_slack(webhook_url, count):\n    \"\"\"\n    Posts build_message(count) to a Slack Incoming Webhook.\n\n    Silently does nothing if webhook_url is empty - Slack notification\n    is optional for this project, and a missing webhook shouldn't fail\n    a run that otherwise completed successfully.\n    \"\"\"\n    if not webhook_url:\n        return\n\n    try:\n        requests.post(webhook_url, json={\"text\": build_message(count)}, timeout=10)\n    except requests.RequestException as problem:\n        # A dead webhook is annoying, not catastrophic - the drafts\n        # themselves were already saved successfully by this point.\n        print(f\"Could not reach Slack (drafts were still saved): {problem}\")\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the message text is right - no\n    # webhook or network call needed:  python notify.py\n    assert build_message(1) == \"1 stale deal just got an AI-drafted follow-up - check your Gmail drafts!\"\n    assert build_message(3) == \"3 stale deals just got AI-drafted follow-ups - check your Gmail drafts!\"\n    print(\"Message text correct for both singular and plural counts.\")\n\n    print(\"\\nChecking an empty webhook URL does nothing (and doesn't crash)...\")\n    notify_slack(\"\", 5)\n    print(\"Confirmed: no request attempted with an empty URL.\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python notify.py`. You should see the singular and plural message text both confirmed correct, then confirmation that an empty webhook URL sends no request, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `main.py` with this code, then run it:",
          "prompt": "\"\"\"\nStep 4 of the CRM Lead Follow-Up Agent (part 4) - the command you\nactually run, ideally every weekday morning.\n\nRun it with:  python main.py\n\"\"\"\n\nimport os\n\nfrom dotenv import load_dotenv\nfrom enrich import enrich_deal\nfrom gmail_draft import get_gmail_service, save_gmail_draft\nfrom hubspot import HubSpot\nfrom hubspot_client import get_stale_deals\nfrom notify import notify_slack\nfrom seen_tracker import filter_unseen, load_seen_ids, save_seen_ids\nfrom writer import write_followup\n\nload_dotenv()\n\n\ndef run():\n    token = os.environ.get(\"HUBSPOT_TOKEN\")\n    hubspot_client = HubSpot(access_token=token)\n    gmail_service = get_gmail_service()\n\n    seen_ids = load_seen_ids()\n    stale_deals = get_stale_deals()\n    fresh_deals = filter_unseen(stale_deals, seen_ids)\n\n    print(f\"{len(stale_deals)} stale deal(s), {len(fresh_deals)} not yet followed up on.\\n\")\n\n    drafted = 0\n    for deal in fresh_deals:\n        try:\n            enriched = enrich_deal(hubspot_client, deal)\n            email_body = write_followup(enriched)\n        except ValueError as problem:\n            print(f\"Skipped '{deal.properties['dealname']}': {problem}\")\n            continue\n\n        contact = enriched[\"contact\"]\n        to_email = contact[\"email\"] if contact and contact[\"email\"] else \"\"\n        if not to_email:\n            print(f\"Skipped '{deal.properties['dealname']}': no contact email on file.\")\n            continue\n\n        subject = f\"Following up - {deal.properties['dealname']}\"\n        save_gmail_draft(gmail_service, to_email, subject, email_body)\n        seen_ids.add(deal.id)\n        drafted += 1\n        print(f\"Drafted follow-up for: {deal.properties['dealname']}\")\n\n    save_seen_ids(seen_ids)\n    notify_slack(os.environ.get(\"SLACK_WEBHOOK_URL\", \"\"), drafted)\n    print(f\"\\nDone. {drafted} new draft(s) created.\")\n\n\nif __name__ == \"__main__\":\n    run()\n",
          "verify": "The first time you run `python main.py`, a browser tab opens for Gmail login (gmail.compose scope only). After that, check Gmail Drafts - you should see one draft per stale deal with a real contact email, personalized body, and no pricing language. Run it a second time immediately - it should now print `0 stale deal(s) not yet followed up on` for every deal from the first run, since seen_deals.json remembers them."
        }
